targets.expr:
topk(5, 
  avg by (ceph_daemon, hostname) (
    ceph_osd_apply_latency_ms{job=~"$job"} 
    * on(ceph_daemon) group_left(hostname) 
    (max by (ceph_daemon, hostname) (ceph_osd_metadata{device_class="nvme", job=~"$job"}))
  )
)

topk(5, 
  ceph_osd_apply_latency_ms{job=~"$job"} 
  * on(ceph_daemon) group_left(hostname) 
  (max by (ceph_daemon, hostname) (ceph_osd_metadata{device_class="ssd", job=~"$job"}))
)
